//! 🔗️ Immutable first-party aliases share one retained clone lifecycle without copying their payload graph.
use super::*;
/// 🎟️ A defining immutable owner declares its actual alias operation independently of payload cloning.
pub trait RetainedAlias:RetireOwned+Sync{fn alias_demand(&self)->RetirementDemand;fn alias_work_demand(&self)->u64;fn admit_alias(&self,grant:RetainedCloneGrant)->RetainedWorkOutcome<(Self,RetainedCloneProgress)>where Self:Sized;}
struct AliasState<T:RetainedAlias>{output:Option<T>,source:Option<RetainedCloneBinding>,close:RetainedCloneClose,closing:bool,spent:bool}
/// 🧷️ The original source remains issued until the result and every cancelled alias physically close.
pub struct RetainedAliasCursor<T:RetainedAlias>{state:ManuallyDrop<AliasState<T>>}
impl<T:RetainedAlias> Default for RetainedAliasCursor<T>{fn default()->Self{Self{state:ManuallyDrop::new(AliasState{output:None,source:None,close:Default::default(),closing:false,spent:false})}}}
fn alias_invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,"original immutable alias changed its source or lifecycle")}
impl<T:RetainedAlias+RetainedClone> RetainedCloneCursor<T> for RetainedAliasCursor<T>{
 fn output_ready(&self)->bool{!self.state.closing&&!self.state.spent&&self.state.output.is_some()}
 fn advance_demands(&self,source:RetainedCloneRef<'_,T>,_:usize,maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.state.closing||self.state.spent||self.state.output.is_some(){return Err(alias_invalid())}let binding=source.binding_demand(&self.state.source)?;let work=if binding.is_some(){1}else{source.get().alias_work_demand()};if work>maximum_work_units{return Ok(Default::default())}Ok(binding.unwrap_or_else(||source.get().alias_demand()))}
 fn advance_work_demand(&self,source:RetainedCloneRef<'_,T>,_:usize,maximum_work_units:u64)->Result<u64,ValueError>{if self.state.closing||self.state.spent||self.state.output.is_some(){return Err(alias_invalid())}let work=if source.binding_demand(&self.state.source)?.is_some(){1}else{source.get().alias_work_demand()};Ok(if work<=maximum_work_units{work}else{0})}
 fn advance(&mut self,source:RetainedCloneRef<'_,T>,body:usize,maximum_work_units:u64,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementOutcome{let g=effect.grant();let maximum_work_units=maximum_work_units.min(effect.maximum_work_units());let mut work=0;let result=(|| -> Result<RetainedCloneStep,crate::OriginalRetirementFailure>{let d=self.advance_demands(source,body,maximum_work_units)?;let required=if source.binding_demand(&self.state.source)?.is_some(){1}else{source.get().alias_work_demand()};if required>maximum_work_units{return Ok(RetainedCloneStep::Progress(Default::default()))}if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if let Some(p)={let turn=source.bind(&mut self.state.source,g);work+=turn.work;turn.result}?{return Ok(RetainedCloneStep::Progress(p))}let turn=source.get().admit_alias(g);work+=turn.work;let(output,p)=turn.result?;self.state.output=Some(output);Ok(RetainedCloneStep::Complete(p))})();RetainedWorkOutcome{result,work}}
 fn take_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(self.output_ready()))}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{crate::retained_clone::retained_clone_cursor_take_demand::<T,bool>()}
    fn take<'reply>(&mut self,output:&mut Option<T>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:crate::retained_clone::OriginalEffectReply<'reply,RetainedCloneStep,ValueError>)->Result<crate::retained_clone::OriginalEffectReplyComplete<'reply,RetainedCloneStep,ValueError>,ValueError>{crate::retained_clone::take_retained_clone_cursor_output!(self.output_ready(),self.state.output,output,self.state.spent,true,effect,reply,T,bool)}
 fn begin_close_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(!self.state.closing))}
 fn begin_close_demand(&self)->Result<crate::RetirementDemand,crate::ValueError>{let flags=usize::from(!self.state.closing);Ok(crate::RetirementDemand{copy_bytes:flags*std::mem::size_of::<bool>(),depth:usize::from(flags!=0),..Default::default()})}
fn begin_close_paid(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::RetainedWorkOutcome<crate::RetainedCloneProgress,crate::ValueError>{crate::retained_clone::start_retained_close(&mut self.state.closing,effect)}
 
 fn close_started(&self)->bool{self.state.closing}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.state.closing{return Ok(0)}self.state.close.next_owner_work::<T>(self.state.output.is_some(),&self.state.source,body)}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.state.closing{return Err(alias_invalid())}self.state.close.next_owner_demands::<T>(self.state.output.is_some(),&self.state.source,body)}
 fn close_step(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>)->crate::OriginalRetirementOutcome{let g=effect.grant();let mut work=0;let result=(|| -> Result<RetainedCloneStep,crate::OriginalRetirementFailure>{let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.state.close.is_empty(){let turn=self.state.close.step_granted(effect);work+=turn.work;return turn.result}let state=&mut*self.state;{let turn=state.close.begin_granted(&mut state.output,effect);work+=turn.work;if let Some(step)=turn.result?{return Ok(step)}}{let turn=RetainedCloneBinding::close_one(&mut state.source,effect);work+=turn.work;turn.result}})();RetainedWorkOutcome{result,work}}
 fn terminal_is_empty(&self)->bool{self.state.output.is_none()&&self.state.source.is_none()&&self.state.close.is_empty()}
 fn next_close_copy_byte_demand(&self)->Result<usize,ValueError>{self.state.close.next_copy_with_binding(&self.state.source)}
 fn next_close_capacity_byte_demand(&self,body:usize)->Result<usize,ValueError>{self.state.close.next_owner_capacity_with_binding::<T>(self.state.output.is_some(),body,&self.state.source)}
 fn next_close_release_byte_demand(&self)->Result<usize,ValueError>{self.state.close.next_release_with_binding(&self.state.source)}
 fn next_close_depth_demand(&self)->Result<usize,ValueError>{self.state.close.next_owner_depth_with_binding(self.state.output.is_some(),&self.state.source)}
}
impl<T:RetainedAlias> Drop for RetainedAliasCursor<T>{fn drop(&mut self){if self.state.output.is_none()&&self.state.source.is_none()&&self.state.close.is_empty(){unsafe{ManuallyDrop::drop(&mut self.state)}}else{assert!(std::thread::panicking(),"original immutable alias requires funded closure")}}}
